/// Returns the maximum element in a non-empty slice of i32.
///
/// Precondition: `arr.len() > 0`.
fn maxArrayReverse(arr: &[i32]) -> i32 {
    // Start from the last element (consistent with "Reverse" in the name),
    // then scan backwards to the front.
    let mut i = arr.len() - 1;
    let mut max = arr[i];

    while i > 0 {
        i -= 1;
        let v = arr[i];
        if v > max {
            max = v;
        }
    }

    max
}

